using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Collections.Generic;using System.Threading;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
public static class V12Tests {
 static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Walk(System.Windows.Media.VisualTreeHelper.GetChild(root,i)))yield return child;} static List<string> log=new List<string>();static void Check(bool okay,string message){if(!okay)throw new Exception(message);log.Add("PASS "+message);}
 static void Pump(Func<bool> ready,int timeout=15000){var watch=Stopwatch.StartNew();while(!ready()){if(watch.ElapsedMilliseconds>timeout)throw new Exception("timed out");var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);Thread.Sleep(5);}}
 static void Delay(int ms){var clock=Stopwatch.StartNew();Pump(()=>clock.ElapsedMilliseconds>=ms,ms+3000);}
 public static int Run(string folder,bool remote){SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));Directory.CreateDirectory(folder);AppDomain.CurrentDomain.UnhandledException+=(s,e)=>File.WriteAllText(Path.Combine(folder,"unhandled.txt"),e.ExceptionObject.ToString());try{
 var text=new TextBlock();var host=new Window{Width=300,Height=150,Content=text,ShowInTaskbar=false};host.Show();NumericMotion.Text(text,"10.0%");var number=NumericMotion.For(text);NumericMotion.Text(text,"90.0%");if(Motion.Enabled){Check(number.IsAnimating,"number update schedules shared animation");number.Advance(450);Check(Math.Abs(number.DisplayValue-80)<.001,"900ms HTML cubic ease-out midpoint = 87.5 percent of change");number.Advance(900);Check(text.Text=="90.0%"&&!number.IsAnimating,"number settles exactly with precision and unit");NumericMotion.Text(text,"10.0%");Delay(160);number.Frame(MotionClock.Now);double falling=number.DisplayValue;Check(falling>10&&falling<90,"falling number has intermediate frames");NumericMotion.Text(text,"70.0%");Check(Math.Abs(number.DisplayValue-falling)<5,"retarget preserves displayed value");Delay(1000);Check(text.Text=="70.0%","retarget settles");NumericMotion.Text(text,"30.0%");NumericMotion.Text(text,"—");Delay(100);Check(text.Text=="—"&&!number.IsAnimating,"unavailable value cancels numeric animation");host.Hide();host.Show();Check(text.Text=="—","hide and show never restore a stale unavailable number");NumericMotion.Text(text,"12.5%");Check(text.Text=="12.5%","first valid number after unavailable is exact");NumericMotion.Text(text,"45.0%");NumericMotion.Text(text,"10 / 100 MiB");NumericMotion.Text(text,"50 / 100 MiB");number.Advance(450);Check(text.Text=="45 / 100 MiB","paired values animate independently with fixed capacity");NumericMotion.Text(text,"21 W");Check(text.Text=="21 W","changing numeric shape safely resets animation");NumericMotion.Text(text,"22 W");host.Hide();Check(!number.IsAnimating,"hidden number unregisters from shared clock");}host.Close();
 var local=new Server{IsLocal=true,Name="本机"};string root=Path.Combine(folder,"copy-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string src=Path.Combine(root,"source.txt"),dst=Path.Combine(root,"copy.txt");File.WriteAllText(src,"copy undo source 内容",Encoding.UTF8);using(var q=new FileTransferQueue(Dispatcher.CurrentDispatcher)){var j=new FileTransfer(local,true,src,dst,false,new FileInfo(src).Length,root);q.Add(j);Pump(()=>!j.IsRunning);Check(j.CanUndo&&File.ReadAllBytes(src).SequenceEqual(File.ReadAllBytes(dst)),"new copy supports undo; source is retained");q.Undo(j);q.Undo(j);q.Retry(j);Pump(()=>!j.IsRunning);Check(j.State=="已撤销"&&!File.Exists(dst)&&File.Exists(src),"undo is idempotent and preserves source; retry cannot race");
 var changed=new FileTransfer(local,true,src,dst,false,new FileInfo(src).Length,root);q.Add(changed);Pump(()=>!changed.IsRunning);var bytes=File.ReadAllBytes(dst);bytes[0]^=1;File.WriteAllBytes(dst,bytes);File.SetLastWriteTimeUtc(dst,changed.CopyStamp);q.Undo(changed);Pump(()=>!changed.IsRunning);Check(changed.State=="已完成"&&File.ReadAllBytes(dst).SequenceEqual(bytes),"same-size same-timestamp changed destination is preserved by SHA256 check");Check(Directory.GetFiles(root,"*.aq-undo-*").Length==0,"refused undo restores original target name");
 File.WriteAllText(dst,"previous content");var replace=new FileTransfer(local,true,src,dst,true,new FileInfo(src).Length,root);q.Add(replace);Pump(()=>!replace.IsRunning);q.Undo(replace);Check(replace.State=="已完成"&&!replace.CanUndo&&File.Exists(dst)&&File.Exists(src),"overwrite task explicitly excludes unsafe undo");
 var canceled=new FileTransfer(local,true,src,Path.Combine(root,"canceled.txt"),false,new FileInfo(src).Length,root);canceled.CancelSource.Cancel();q.Add(canceled);Pump(()=>!canceled.IsRunning);q.Undo(canceled);Check(canceled.State=="已取消"&&!canceled.CanUndo,"canceled tasks cannot undo");q.Retry(canceled);Pump(()=>!canceled.IsRunning);Check(canceled.CanUndo,"retry creates its own valid undo receipt");q.Undo(canceled);Pump(()=>!canceled.IsRunning);Check(canceled.State=="已撤销","retried copy can undo");}
 if(remote){var device=Storage.DefaultServer();string remoteRoot;using(var c=new FileConnection(device)){c.Connect(CancellationToken.None).GetAwaiter().GetResult();remoteRoot=c.Home.TrimEnd('/')+"/.aqserver-test-v12-"+Guid.NewGuid().ToString("N");c.MakeDirectory(remoteRoot);}using(var q=new FileTransferQueue(Dispatcher.CurrentDispatcher)){string remoteFile=remoteRoot+"/copy.txt";var up=new FileTransfer(device,true,src,remoteFile,false,new FileInfo(src).Length);q.Add(up);Pump(()=>!up.IsRunning,60000);Check(up.CanUndo,"real SFTP upload has undo receipt");string downloaded=Path.Combine(root,"download.txt");var down=new FileTransfer(device,false,remoteFile,downloaded,false,new FileInfo(src).Length,root);q.Add(down);Pump(()=>!down.IsRunning,60000);Check(down.CanUndo&&File.ReadAllBytes(src).SequenceEqual(File.ReadAllBytes(downloaded)),"SFTP roundtrip SHA256 and original retained");q.Undo(down);Pump(()=>!down.IsRunning,60000);Check(down.State=="已撤销"&&!File.Exists(downloaded),"SFTP download undo removes local copy");q.Undo(up);Pump(()=>!up.IsRunning,60000);using(var c=new FileConnection(device)){c.Connect(CancellationToken.None).GetAwaiter().GetResult();Check(up.State=="已撤销"&&!c.Exists(remoteFile)&&File.Exists(src),"SFTP upload undo removes remote copy only");c.RemoveOwnTestDirectory(remoteRoot);}}}
 var window=new MonitorWindow(true);window.SwitchView("文件");var view=window.FileView;view.SetServer(local);string visual=Path.Combine(root,"visual");Directory.CreateDirectory(visual);view.Navigate(visual,true,true);Pump(()=>!view.IsLoading);view.UploadFromWindows(local,visual,new[]{src});Pump(()=>view.AllTransfers.Any()&&view.AllTransfers.All(x=>!x.Item2.IsRunning));view.TransferTable.SelectedItem=view.AllTransfers.First().Item2;
 foreach(string theme in new[]{"graphite","light"}){window.ApplyAppearance(theme);view.SetServer(local);view.Navigate(visual,true,true);Pump(()=>!view.IsLoading);view.TransferTable.SelectedItem=view.AllTransfers.First().Item2;foreach(int width in new[]{760,1200}){window.RenderImage(Path.Combine(folder,theme+"-transfers-"+width+".png"),width,800,120);UiReview.Record(window.Root,Path.Combine(folder,theme+"-transfers-"+width+".csv"),"v12 transfer toolbar");Check(window.Audit().Count==0,"transfer page layout "+theme+" "+width);var buttons=Walk(view).OfType<Button>().Where(x=>new[]{"取消","重试","撤销","清除记录"}.Contains(x.Content as string)&&x.ActualWidth>0).ToArray();Check(buttons.Length==4&&buttons.All(x=>Math.Abs(x.ActualHeight-32)<.1),"toolbar button sizes "+theme+" "+width);var y=buttons.Select(x=>x.TranslatePoint(new Point(0,0),view).Y).ToArray();Check(y.Max()-y.Min()<.1,"toolbar buttons share vertical alignment "+theme+" "+width);}}
 window.Exit();window.Restore();Check(!window.IsVisible,"late restore after exit is safely ignored");Check(MotionClock.ActiveCount==0,"no remaining frame animation after closing windows");File.WriteAllLines(Path.Combine(folder,"v12-results.txt"),log);return 0;
 }catch(Exception ex){File.WriteAllLines(Path.Combine(folder,"v12-results.txt"),log);File.WriteAllText(Path.Combine(folder,"v12-error.txt"),ex.ToString());return 1;}}
}
